# src/schemas.py
from typing import Literal
from pydantic import BaseModel, field_validator

class TransaksiInput(BaseModel):
    jenis: Literal["pemasukan", "pengeluaran"]      # nilai lain → ditolak otomatis
    deskripsi: str
    jumlah: int                                      # rupiah bulat — bukan float (uang!)

    @field_validator("deskripsi")
    @classmethod
    def deskripsi_wajib(cls, v: str) -> str:
        if not v.strip():
            raise ValueError("deskripsi wajib diisi")     # pesan sama dgn validasi() Go
        return v.strip()

    @field_validator("jumlah")
    @classmethod
    def jumlah_positif(cls, v: int) -> int:
        if v <= 0:
            raise ValueError("jumlah harus lebih dari 0")
        return v

class Transaksi(TransaksiInput):
    id: int
    tanggal: str

