from fastapi import APIRouter
from .. import store

router = APIRouter(prefix="/api/ringkasan", tags=["ringkasan"])

@router.get("")
def ringkasan():
    data = store.semua()
    pemasukan   = sum(t["jumlah"] for t in data if t["jenis"] == "pemasukan")
    pengeluaran = sum(t["jumlah"] for t in data if t["jenis"] == "pengeluaran")
    return {"pemasukan": pemasukan, "pengeluaran": pengeluaran,
            "saldo": pemasukan - pengeluaran}

# pola DI: rantai dependensi session → repo → service → router
from fastapi import Depends

async def get_session():                      # Bab 2
    async with Session() as s:
        yield s                               # yield = cleanup otomatis setelah respons

def get_repo(s = Depends(get_session)) -> TransaksiRepo:
    return TransaksiRepo(s)

def get_service(r = Depends(get_repo)) -> TransaksiService:
    return TransaksiService(r)

@router.post("", status_code=201)
async def buat(masuk: TransaksiInput, svc: TransaksiService = Depends(get_service)):
    return await svc.buat(masuk)              # router tipis: delegasi saja

# src/services/transaksi.py — aturan bisnis + error domain
class AppError(Exception):
    def __init__(self, pesan: str, status: int = 400):
        self.pesan, self.status = pesan, status

class TransaksiService:
    def __init__(self, repo): self.repo = repo

    async def hapus(self, id: int):
        if not await self.repo.hapus(id):
            raise AppError("transaksi tidak ditemukan", 404)

# main.py — satu handler untuk error domain → kontrak {error}
@app.exception_handler(AppError)
async def app_err(req, exc: AppError):
