from rest_framework import serializers
from .models import Transaksi

class TransaksiSerializer(serializers.ModelSerializer):
    class Meta:
        model = Transaksi
        fields = ["id", "jenis", "deskripsi", "jumlah", "tanggal"]
        read_only_fields = ["id", "tanggal"]

    def validate_deskripsi(self, v):
        if not v.strip():
            raise serializers.ValidationError("deskripsi wajib diisi")
        return v.strip()

    def validate_jumlah(self, v):
        if v <= 0:
            raise serializers.ValidationError("jumlah harus lebih dari 0")
        return v

